  params,
  env
) {
  return readMarketHistoryForContract({
    db: env?.DATA_DB,
    contract: normalizeFuturesContract(params?.contract || params?.contract_code || 'ETHFI-USDT'),
    hours: clamp(params?.hours, 0.25, 168, 6),
