callers.Worker_historyMetrics:
function historyMetrics(
  current,
  row,
  history_options=null
) {
  if(current?.venue==='BINGX'||row?.venue==='BINGX'){
    const result=compareBingxHistoryPoint({...history_options,current,prior:row});
    return {...result,state:typeof result.price_change_pct==='number'&&typeof result.oi_change_pct==='number'?stageState(result.price_change_pct,result.oi_change_pct):'insufficient'};
  }
  if (!row) {
    return {
      available: false,
      price_change_pct: null,
      oi_change_pct: null,
      funding_change_pct_points: null,
      turnover_24h_change_pct: null,
      state: "insufficient",
    };
  }

  const priceChange =
    pctDelta(
      current.price,
      row.price
    );

  const oiChange =
    pctDelta(
      current.oi_contracts,
      row.oi_contracts
    );

  const fundingNow =
    num(
      current.funding_rate
    );

  const fundingPrior =
    num(
      row.funding_rate
    );

  const fundingDelta =
    fundingNow !== null &&
    fundingPrior !== null
      ? (
          fundingNow -
          fundingPrior
        ) * 100
      : null;

  return {
    available: true,

    reference_ts:
      row.ts,

    reference_time:
      iso(row.ts),

    price_change_pct:
      priceChange,

    oi_change_pct:
      oiChange,

    funding_change_pct_points:
      fundingDelta,

    turnover_24h_change_pct:
      pctDelta(
        current.turnover_24h,
        row.turnover_24h
      ),

    prior_discovery:
      row?.prior_discovery ||
      null,

    state:
      stageState(
        priceChange,
        oiChange
      ),
  };
}

